package za.ac.smartpantry;
import android.app.*;import android.os.*;import android.widget.*;
public class RecipeDetailActivity extends Activity{@Override public void onCreate(Bundle b){super.onCreate(b);setContentView(R.layout.activity_recipe_detail);PantryDatabase db=new PantryDatabase(this);Recipe recipe=db.getRecipe(getIntent().getLongExtra("id",-1));if(recipe==null){finish();return;}((TextView)findViewById(R.id.recipeTitle)).setText(recipe.title);StringBuilder needs=new StringBuilder();for(Ingredient i:db.getNeeds(recipe.id))needs.append("• ").append(i.name).append(" — ").append(i.quantity).append(" ").append(i.unit).append("\n");((TextView)findViewById(R.id.recipeIngredients)).setText(needs.toString());((TextView)findViewById(R.id.recipeMethod)).setText(recipe.method);findViewById(R.id.backButton).setOnClickListener(v->finish());}}